<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\Category;use Illuminate\Http\Request;use Illuminate\Support\Str;
class CategoryController extends Controller {public function index(){ $categories=Category::withCount('reports')->orderBy('name')->get();return view('admin.categories.index',compact('categories'));}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:100|unique:categories,name','description'=>'nullable|string|max:500']);Category::create($d+['slug'=>Str::slug($d['name']),'is_active'=>true]);return back()->with('success','Kategori ditambahkan.');}public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|string|max:100|unique:categories,name,'.$category->id,'description'=>'nullable|string|max:500','is_active'=>'required|boolean']);$d['slug']=Str::slug($d['name']);$category->update($d);return back()->with('success','Kategori diperbarui.');}}
